using System.Collections.Generic;
using UnityEngine;

namespace BiolaCampus.World
{
    /// <summary>
    /// Runtime materials. Prefers materials generated by the editor setup under
    /// Resources/BiolaMaterials (guarantees the shaders are in the build), falls back to Shader.Find.
    /// </summary>
    public static class MaterialLibrary
    {
        static readonly Dictionary<string, Material> Cache = new Dictionary<string, Material>();

        public static Material Lit(string name, Color color) => Get(name, color, "Standard", "Legacy Shaders/Diffuse");
        public static Material Unlit(string name, Color color) => Get(name, color, "Unlit/Color", "Sprites/Default");

        static Material Get(string name, Color color, params string[] shaders)
        {
            if (Cache.TryGetValue(name, out var m) && m != null) return m;
            var template = Resources.Load<Material>("BiolaMaterials/" + name);
            if (template != null) m = new Material(template);
            else
            {
                Shader sh = null;
                foreach (var s in shaders) { sh = Shader.Find(s); if (sh != null) break; }
                if (sh == null) sh = Shader.Find("Hidden/InternalErrorShader");
                m = new Material(sh);
            }
            m.color = color;
            m.name = name;
            Cache[name] = m;
            return m;
        }
    }
}
